function drawDeerFullBodyReference(a, stage, sleeping) {
  const state = sleeping ? "sleep" : "awake";
  const img = DEER_FULL_BODY_REFERENCE_IMAGES[stage]?.[state];
  if (!img || !img.complete || !img.naturalWidth || !img.naturalHeight) return false;

  const stageScale = UPLOADED_ANIMAL_STAGE_VISUAL_SCALE[stage] || 1.52;
  const antlerStage = stage !== "baby";
  const meta = {
    drawHMul: stageScale,
    anchorX: 0.50,
    anchorY: 0.50,
    overlap: sleeping ? 0.045 : 0.055,
    tailEnd: sleeping ? 0.22 : 0.24,
    // Deer antlers/horns are part of the moving head piece.
    // Start the head cut farther back so the lighter tan antlers stay with the head.
    headStart: antlerStage ? (sleeping ? 0.50 : 0.49) : (sleeping ? 0.69 : 0.70),
    tailPivot: 0.31,
    headPivot: antlerStage ? (sleeping ? 0.54 : 0.55) : (sleeping ? 0.65 : 0.66),
    tailRotBase: sleeping ? 0.03 : -0.03,
    tailRotAmp: sleeping ? 0.12 : 0.30,
    headRotAmp: antlerStage ? (sleeping ? 0.08 : 0.19) : (sleeping ? 0.06 : 0.16),
    headPush: antlerStage ? (sleeping ? 0.07 : 0.19) : (sleeping ? 0.05 : 0.16),
    shadow: { x: -0.03, y: 0.30, rx: 1.08, ry: 0.26 }
  };
  const box = { x: 0, y: 0, w: img.naturalWidth, h: img.naturalHeight };
  return drawCuteSegmentedReferenceAnimal(a, "deer", stage, meta, img, box);
}


