function getDogFullBodyReferenceImage(stage, sleeping) {
  const state = sleeping ? "sleep" : "awake";
  if (sleeping && CUSTOM_SLEEP_PET_IMAGES?.dog?.[stage]) {
    return CUSTOM_SLEEP_PET_IMAGES.dog[stage];
  }
  if (CUSTOM_STAGE_PET_IMAGES?.dog?.[stage]) {
    return CUSTOM_STAGE_PET_IMAGES.dog[stage];
  }
  // If a special sleeping reference is missing, stay on the awake dog art
  // instead of changing size or shape unpredictably.
  return CUSTOM_SLEEP_PET_IMAGES?.dog?.[stage] || null;
}

function drawCuteSegmentedReferenceAnimal(a, type, stageKey, meta, img, box) {
  if (!img || !img.complete || !img.naturalWidth || !img.naturalHeight || !box) return false;

  const hornHeadCarrier =
    (type === "deer" && stageKey !== "baby") ||
    (type === "owl");
  // Deer antlers sit farther back than the tan face, so for non-baby deer
  // the moving head piece must start earlier and carry the antlers too.
  const tunedMeta = hornHeadCarrier
    ? {
        ...meta,
        headStart: meta.headStartOverride ?? (
          type === "deer"
            ? (a.sleeping ? 0.50 : 0.49)
            : (a.sleeping ? 0.60 : 0.59)
        ),
        headPivot: meta.headPivotOverride ?? (
          type === "deer"
            ? (a.sleeping ? 0.54 : 0.55)
            : (a.sleeping ? 0.58 : 0.59)
        ),
        headRotAmp: Math.max(meta.headRotAmp ?? 0, type === "deer" ? (a.sleeping ? 0.08 : 0.19) : (a.sleeping ? 0.07 : 0.14)),
        headPush: Math.max(meta.headPush ?? 0, type === "deer" ? (a.sleeping ? 0.07 : 0.19) : (a.sleeping ? 0.06 : 0.12))
      }
    : meta;

  const r = Math.max(8, Number(a.r) || 18);
  const drawH = r * (tunedMeta.drawHMul || 2.0);
  const drawW = drawH * (box.w / Math.max(1, box.h));
  const scale = drawH / Math.max(1, box.h);
  const x0 = -drawW * (tunedMeta.anchorX ?? 0.5);
  const y0 = -drawH * (tunedMeta.anchorY ?? 0.5);
  const overlap = box.w * (tunedMeta.overlap ?? 0.045);

  const tailEnd = box.x + box.w * (tunedMeta.tailEnd ?? 0.36);
  const headStart = box.x + box.w * (tunedMeta.headStart ?? 0.62);
  const tailPivotX = box.x + box.w * (tunedMeta.tailPivot ?? 0.40);
  const headPivotX = box.x + box.w * (tunedMeta.headPivot ?? 0.67);
  const centerY = box.y + box.h * 0.5;

  const tailPart = {
    sx: box.x,
    sy: box.y,
    sw: Math.max(1, Math.round(tailEnd - box.x + overlap)),
    sh: box.h,
    px: tailPivotX,
    py: centerY
  };
  const bodyPart = {
    sx: Math.max(box.x, Math.round(tailEnd - overlap)),
    sy: box.y,
    sw: Math.max(1, Math.round((headStart - tailEnd) + overlap * 2)),
    sh: box.h
  };
  const headPart = {
    sx: Math.max(box.x, Math.round(headStart - overlap)),
    sy: box.y,
    sw: Math.max(1, Math.round((box.x + box.w) - (headStart - overlap))),
    sh: box.h,
    px: headPivotX,
    py: centerY
  };

  const nowMs = performance.now();
  const lastVisualAt = Number(a._cuteVisualAt) || nowMs;
  const visualDt = Math.max(0, Math.min(0.05, (nowMs - lastVisualAt) / 1000));
  a._cuteVisualAt = nowMs;

  const recentlyMoved = (nowMs - (a._visualMoveAt || 0)) < 170;
  const actualMoveSpeed = (!a.sleeping && recentlyMoved) ? Math.max(0, Number(a._visualMoveSpeed) || 0) : 0;
  const normalMoveSpeed = Math.max(1, Number(a.speed) || animalSpeed(type, stageKey, !!a.owned) || 1);
  const measuredMoveRatio = Math.max(0, Math.min(1.8, actualMoveSpeed / normalMoveSpeed));
  const rawMoveRatio = (net.room && Number.isFinite(a._netAnimMoveRatio))
    ? Math.max(0, Math.min(1.8, a._netAnimMoveRatio))
    : measuredMoveRatio;

  const targetCuteMotion = a.sleeping ? 0.06 : Math.max(0.20, Math.min(0.82, rawMoveRatio * 0.70 + 0.08));
  const prevCuteMotion = Number(a._cuteMotion) || 0;
  const response = 1 - Math.exp(-visualDt * (targetCuteMotion > prevCuteMotion ? 7.2 : 4.8));
  const moveRatio = prevCuteMotion + (targetCuteMotion - prevCuteMotion) * response;
  a._cuteMotion = moveRatio;

  const attackT = Math.max(0, Math.min(1, Number(a.attackAnim) || 0));
  const bite = Math.sin(attackT * Math.PI);
  const motionTime = nowMs * 0.001;

  const attackPush = a.sleeping ? 0 : bite * r * 0.08;
  const bobPhase = (net.room && Number.isFinite(a._netAnimPhase))
    ? a._netAnimPhase * 0.46 + 0.25
    : (a.sleeping
      ? motionTime * 2.0 + (a.x || 0) * 0.01
      : motionTime * (2.4 + moveRatio * 1.0) + (a.x || 0) * 0.008);
  const mainBob = Math.sin(bobPhase) * r *
    (a.sleeping ? 0.012 : (0.008 + moveRatio * 0.012));

  const sleepTailTuck = a.sleeping ? (type === "cat" ? 0.18 : type === "fox" ? 0.14 : type === "dog" ? 0.12 : 0.10) : 0;
  const sleepTailShift = a.sleeping ? r * (type === "cat" ? 0.14 : type === "fox" ? 0.12 : 0.10) : 0;

  const tailFrequency = (a.sleeping ? 1.2 : 1.9) + rawMoveRatio * 6.2;
  const stablePhase = (net.room && Number.isFinite(a._netAnimPhase))
    ? a._netAnimPhase
    : motionTime * tailFrequency + (a.tailPhase || 0);
  const tailSwing = Math.sin(stablePhase);
  const tailLift = Math.cos(stablePhase * 0.72 + 0.35);
  const tailAngle = (tunedMeta.tailRotBase ?? -0.04) + sleepTailTuck +
    tailSwing * (tunedMeta.tailRotAmp ?? 0.24) * (a.sleeping ? 0.14 : (0.24 + moveRatio * 0.58));
  const tailDy = a.sleeping ? 0 : tailLift * r * (0.006 + moveRatio * 0.011);

  const headFrequency = (a.sleeping ? 1.0 : 1.55) + rawMoveRatio * 3.0;
  const headPhase = (net.room && Number.isFinite(a._netAnimPhase))
    ? a._netAnimPhase * 0.72 + 0.8
    : motionTime * headFrequency + (a.x || 0) * 0.009 + (a.tailPhase || 0) * 0.30;
  const headTurn = Math.sin(headPhase) *
    (tunedMeta.headRotAmp ?? 0.09) * (a.sleeping ? 0.12 : (0.26 + moveRatio * 0.56));
  const headNod = Math.cos(headPhase * 0.82 + 0.45) *
    r * (a.sleeping ? 0.005 : (0.010 + moveRatio * 0.016));
  const headLift = Math.sin(headPhase * 0.92 + 0.8) *
    r * (a.sleeping ? 0.004 : (0.006 + moveRatio * 0.011));
  const headAngle = headTurn + bite * (tunedMeta.headRotAmp ?? 0.07) * 0.95;
  const headTx = bite * (tunedMeta.headPush ?? 0.18) * r;
  const headTy = headNod - headLift;

  function drawStatic(part) {
    ctx.drawImage(
      img,
      part.sx, part.sy, part.sw, part.sh,
      x0 + (part.sx - box.x) * scale,
      y0 + (part.sy - box.y) * scale,
      part.sw * scale,
      part.sh * scale
    );
  }

  function drawRotated(part, rot, tx = 0, ty = 0) {
    ctx.save();
    ctx.translate(x0 + (part.px - box.x) * scale + tx, y0 + (part.py - box.y) * scale + ty);
    ctx.rotate(rot);
    ctx.drawImage(
      img,
      part.sx, part.sy, part.sw, part.sh,
      (part.sx - part.px) * scale,
      (part.sy - part.py) * scale,
      part.sw * scale,
      part.sh * scale
    );
    ctx.restore();
  }

  ctx.save();
  ctx.fillStyle = "rgba(0,0,0,0.15)";
  ctx.beginPath();
  ctx.ellipse(
    (tunedMeta.shadow?.x ?? -0.05) * r,
    (tunedMeta.shadow?.y ?? 0.20) * r,
    (tunedMeta.shadow?.rx ?? 1.05) * r,
    (tunedMeta.shadow?.ry ?? 0.28) * r,
    0, 0, TAU
  );
  ctx.fill();

  const oldSmooth = ctx.imageSmoothingEnabled;
  const oldQuality = ctx.imageSmoothingQuality;
  ctx.imageSmoothingEnabled = true;
  try { ctx.imageSmoothingQuality = "high"; } catch (_) {}

  ctx.translate(attackPush, mainBob);

  // Draw tail below body, body in the middle, head on top.
  drawRotated(tailPart, tailAngle, sleepTailShift, tailDy);
  drawStatic(bodyPart);
  drawRotated(headPart, headAngle, headTx, headTy);

  if (player.riding === a) {
    const saddle = tunedMeta.saddle || { x: -0.05, y: -0.02, w: 0.68, h: 0.40 };
    drawMountedSaddleOnCustom(
      drawW, drawH,
      saddle.x * r,
      saddle.y * r,
      saddle.w * r,
      saddle.h * r
    );
  }

  ctx.imageSmoothingEnabled = oldSmooth;
  try { ctx.imageSmoothingQuality = oldQuality; } catch (_) {}
  ctx.restore();
  return true;
}

function drawDogFullBodyReference(a, stage, sleeping) {
  const img = getDogFullBodyReferenceImage(stage, sleeping);
  if (!img || !img.complete || !img.naturalWidth || !img.naturalHeight) return false;

  const meta = (typeof CUSTOM_PET_SEGMENTS !== "undefined" && CUSTOM_PET_SEGMENTS.dog)
    ? CUSTOM_PET_SEGMENTS.dog
    : {
        drawHMul: 2.0, anchorX: 0.50, anchorY: 0.50,
        tailEnd: 0.34, headStart: 0.57, tailPivot: 0.38, headPivot: 0.60,
        overlap: 0.045, tailRotBase: -0.06, tailRotAmp: 0.28,
        headRotAmp: 0.07, headPush: 0.20,
        shadow: { x: -0.06, y: 0.20, rx: 1.08, ry: 0.29 },
        saddle: { x: -0.05, y: -0.02, w: 0.72, h: 0.42 }
      };

  const box = { x: 0, y: 0, w: img.naturalWidth, h: img.naturalHeight };
  return drawCuteSegmentedReferenceAnimal(a, "dog", stage, meta, img, box);
}


