function getCurrentWholeAnimalReference(type, stage, sleeping) {
  const desiredState = sleeping ? "sleep" : "awake";

  // First prefer the currently active uploaded whole-body animal art, when present.
  const uploadedSpecies = UPLOADED_ANIMAL_SKINS?.[type];
  if (uploadedSpecies) {
    const uploadedStage = uploadedSpecies[stage];
    if (uploadedStage) {
      const selected = uploadedStage[desiredState] || uploadedStage.awake || uploadedStage.sleep;
      if (selected && selected.img && selected.img.complete && selected.img.naturalWidth && selected.img.naturalHeight) {
        return {
          img: selected.img,
          box: { x: 0, y: 0, w: selected.img.naturalWidth, h: selected.img.naturalHeight }
        };
      }
    }
  }

  // Then prefer any whole-body custom stage images already in the game.
  if (sleeping && CUSTOM_SLEEP_PET_IMAGES?.[type]?.[stage]) {
    const img = CUSTOM_SLEEP_PET_IMAGES[type][stage];
    if (img.complete && img.naturalWidth && img.naturalHeight) {
      return { img, box: { x: 0, y: 0, w: img.naturalWidth, h: img.naturalHeight } };
    }
  }
  if (CUSTOM_STAGE_PET_IMAGES?.[type]?.[stage]) {
    const img = CUSTOM_STAGE_PET_IMAGES[type][stage];
    if (img.complete && img.naturalWidth && img.naturalHeight) {
      return { img, box: { x: 0, y: 0, w: img.naturalWidth, h: img.naturalHeight } };
    }
  }

  // Finally fall back to the original in-game reference sprite sheet slice.
  const meta = CUSTOM_PET_SEGMENTS?.[type];
  const refImg = REFERENCE_PET_SPRITES?.[type];
  if (meta && refImg && refImg.complete && refImg.naturalWidth) {
    const box = meta.stages?.[stage] || meta.stages?.adult;
    if (box) return { img: refImg, box };
  }

  return null;
}

function drawWholeAnimalFromCurrentReference(a, type) {
  const meta = CUSTOM_PET_SEGMENTS?.[type];
  if (!meta) return false;

  const stageKey = a.stage === "baby" ? "baby" :
                   a.stage === "boss" ? "boss" :
                   a.stage === "superboss" ? "superboss" :
                   a.stage === "bigmomma" ? "bigmomma" : "adult";

  const ref = getCurrentWholeAnimalReference(type, stageKey, !!a.sleeping);
  if (!ref) return false;

  return drawCuteSegmentedReferenceAnimal(a, type, stageKey, meta, ref.img, ref.box);
}



