// Reference-aligned deer split setup.
// IMPORTANT: these are the ACTUAL separated deer source pieces. The finished
// deer images are used only to determine how these pieces connect at rest.
// The original upload buckets were stage-mislabeled, so sourceStage remaps them:
//   bigmomma bucket -> Adult deer
//   superboss bucket -> Boss deer
//   boss bucket      -> Super Boss deer
//   adult bucket     -> Big Momma deer
const DEER_REFERENCE_ALIGNED_SPLIT_SPECS = {
  adult: {
    awake: {
      sourceStage: "bigmomma", srcW: 168.66663, srcH: 66.80245,
      parts: [[0.0,22.0,0.0],[29.0,93.0,-20.0],[97.0,168.66663,-81.0]]
    },
    sleep: {
      sourceStage: "bigmomma", srcW: 163.93717, srcH: 66.80245,
      parts: [[0.0,19.0,0.0],[28.0,91.0,-20.0],[92.0,163.93717,-78.0]]
    }
  },
  boss: {
    awake: {
      sourceStage: "superboss", srcW: 201.66662, srcH: 66.80245,
      parts: [[0.0,22.0,6.0],[32.0,96.0,-2.0],[105.0,201.66662,-108.0]]
    },
    // No finished Boss-sleep reference was included. Use the same neck/body
    // connection logic as Boss awake, adjusted to the actual sleep source bounds.
    sleep: {
      sourceStage: "superboss", srcW: 190.59495, srcH: 66.80245,
      parts: [[0.0,19.0,6.0],[27.0,91.0,-2.0],[94.0,190.59495,-97.0]]
    }
  },
  superboss: {
    awake: {
      sourceStage: "boss", srcW: 204.66661, srcH: 77.03989,
      // Re-aligned to the user-provided Super Boss deer awake reference.
      // Tail keeps its earlier placement; middle body was too far right.
      // Use the actual separated-piece bounds from the uploaded source bucket.
      parts: [[0.0,23.0,23.0],[27.0,91.0,6.0],[91.0,204.66661,-94.0]]
    },
    sleep: {
      sourceStage: "boss", srcW: 207.66662, srcH: 77.03989,
      // Re-aligned to the user-provided Super Boss deer sleep reference.
      parts: [[0.0,20.0,22.0],[28.0,92.0,5.0],[93.0,207.66662,-95.0]]
    }
  },
  bigmomma: {
    awake: {
      sourceStage: "adult", srcW: 204.86661, srcH: 76.46779,
      parts: [[0.0,22.0,22.0],[27.0,90.0,21.0],[91.0,204.86661,-95.0]]
    },
    sleep: {
      sourceStage: "adult", srcW: 206.06412, srcH: 76.46779,
      parts: [[0.0,19.0,22.0],[28.0,91.0,20.0],[92.0,206.06412,-96.0]]
    }
  }
};

const DEER_REASSEMBLED_SKIN_IMAGES = {};
for (const stage of Object.keys(DEER_REASSEMBLED_SKIN_SOURCES)) {
  DEER_REASSEMBLED_SKIN_IMAGES[stage] = {};
  for (const state of Object.keys(DEER_REASSEMBLED_SKIN_SOURCES[stage])) {
    const img = new Image();
    img.decoding = "async";
    img.src = DEER_REASSEMBLED_SKIN_SOURCES[stage][state];
    DEER_REASSEMBLED_SKIN_IMAGES[stage][state] = img;
  }
}

function drawReassembledDeerPartsSkin(a, stage, sleeping) {
  const state = sleeping ? "sleep" : "awake";
  const spec = DEER_REFERENCE_ALIGNED_SPLIT_SPECS[stage]?.[state];
  const sourceStage = spec?.sourceStage || stage;
  const img = DEER_REASSEMBLED_SKIN_IMAGES[sourceStage]?.[state];
  if (!img || !spec || !img.complete || !img.naturalWidth || !img.naturalHeight) return false;

  const r = Math.max(8, Number(a.r) || 18);
  const stageScale = UPLOADED_ANIMAL_STAGE_VISUAL_SCALE[stage] || 1.9;

  const originalParts = spec.parts.map(p => [p[0], p[1], p[2]]);
  const headPart = originalParts[originalParts.length - 1] || null;
  if (!headPart) return false;

  let tailPart = null;
  let bodyParts = [];
  if (originalParts.length >= 3) {
    tailPart = originalParts[0];
    bodyParts = originalParts.slice(1, -1);
  } else {
    // Some deer stages came with only body+head separated. In those cases,
    // split the body chunk so the tail can still animate independently.
    const base = originalParts[0];
    const width = base[1] - base[0];
    const splitW = Math.max(12, width * 0.26);
    const overlap = Math.max(2, width * 0.04);
    tailPart = [base[0], Math.min(base[1], base[0] + splitW), base[2]];
    bodyParts = [[Math.max(base[0], base[0] + splitW - overlap), base[1], base[2]]];
  }

  const assembledParts = [tailPart, ...bodyParts, headPart];
  let minX = Infinity, maxX = -Infinity;
  for (const part of assembledParts) {
    const x0 = part[0] + part[2];
    const x1 = part[1] + part[2];
    if (x0 < minX) minX = x0;
    if (x1 > maxX) maxX = x1;
  }
  const assembledW = maxX - minX;
  const assembledH = spec.srcH;
  const assembledAspect = assembledW / assembledH;

  const drawH = r * 1.00 * stageScale;
  const drawW = drawH * assembledAspect;
  const scale = drawW / assembledW;
  const left = -drawW * 0.5;
  const top = -drawH * 0.5;

  ctx.save();
  ctx.fillStyle = "rgba(0,0,0,0.15)";
  ctx.beginPath();
  ctx.ellipse(-drawW * 0.03, drawH * 0.30, drawW * 0.31, drawH * 0.14, 0, 0, TAU);
  ctx.fill();

  const oldSmooth = ctx.imageSmoothingEnabled;
  const oldQuality = ctx.imageSmoothingQuality;
  ctx.imageSmoothingEnabled = true;
  try { ctx.imageSmoothingQuality = "high"; } catch (_) {}

  const nowMs = performance.now();
  const recentlyMoved = (nowMs - (a._visualMoveAt || 0)) < 180;
  const actualMoveSpeed = (!a.sleeping && recentlyMoved) ? Math.max(0, Number(a._visualMoveSpeed) || 0) : 0;
  const normalMoveSpeed = Math.max(1, Number(a.speed) || animalSpeed("deer", stage, !!a.owned) || 1);
  const measuredMoveRatio = Math.max(0, Math.min(1.25, actualMoveSpeed / normalMoveSpeed));
  const moveRatio = (net.room && Number.isFinite(a._netAnimMoveRatio))
    ? Math.max(0, Math.min(1.25, a._netAnimMoveRatio))
    : measuredMoveRatio;
  const deerMotionT = nowMs * 0.001;
  const deerPhase = (net.room && Number.isFinite(a._netAnimPhase))
    ? a._netAnimPhase
    : deerMotionT * (2.4 + moveRatio * 6.2) + (a.tailPhase || 0);

  const bodyBob = Math.sin(deerPhase * 0.42 + 0.25) *
    r * (a.sleeping ? 0.002 : (0.004 + moveRatio * 0.006));
  const tailAngle = Math.sin(deerPhase) *
    (a.sleeping ? 0.045 : (0.10 + moveRatio * 0.20));
  const tailLift = Math.cos(deerPhase * 0.72 + 0.4) *
    r * (a.sleeping ? 0.002 : (0.004 + moveRatio * 0.008));
  const headAngle = Math.sin(deerPhase * 0.58 + 0.8) *
    (a.sleeping ? 0.03 : (0.07 + moveRatio * 0.13));
  const headBob = Math.cos(deerPhase * 0.49 + 0.35) *
    r * (a.sleeping ? 0.003 : (0.008 + moveRatio * 0.012));
  // The separated pieces are now reference-aligned at their zero-motion pose,
  // so do not apply a permanent horizontal correction to the head.
  const headPush = 0;

  const srcW = img.naturalWidth;
  const srcH = img.naturalHeight;

  function drawPartStatic(part) {
    const [x0, x1, shift] = part;
    const sx = x0 / spec.srcW * srcW;
    const sw = (x1 - x0) / spec.srcW * srcW;
    const dx = left + ((x0 + shift) - minX) * scale;
    const dw = (x1 - x0) * scale;
    ctx.drawImage(img, sx, 0, sw, srcH, dx, top + bodyBob, dw, drawH);
  }

  function drawPartRotated(part, pivotFrac, angle, tx = 0, ty = 0) {
    const [x0, x1, shift] = part;
    const sx = x0 / spec.srcW * srcW;
    const sw = (x1 - x0) / spec.srcW * srcW;
    const dx = left + ((x0 + shift) - minX) * scale;
    const dw = (x1 - x0) * scale;
    const px = dx + dw * pivotFrac;
    const py = top + drawH * 0.53 + bodyBob + ty;
    ctx.save();
    ctx.translate(px + tx, py);
    ctx.rotate(angle);
    ctx.drawImage(img, sx, 0, sw, srcH, dx - px, top + bodyBob - py, dw, drawH);
    ctx.restore();
  }

  // Deer layering:
  // 1) tail under body
  // 2) torso/body segments
  // 3) full head segment on top, including the tan antlers/horns
  if (tailPart) drawPartRotated(tailPart, 0.95, tailAngle, 0, tailLift);
  for (const part of bodyParts) drawPartStatic(part);
  drawPartRotated(headPart, 0.12, headAngle, headPush, headBob);

  ctx.imageSmoothingEnabled = oldSmooth;
  try { ctx.imageSmoothingQuality = oldQuality; } catch (_) {}
  ctx.restore();
  return true;
}

// Source measurements from the uploaded separated SVG:
// source size 132.66666 × 47.42844
// tail occupies x 0..22.5 and is already in its final position
// middle/body occupies x 26.75..90.25 and must move LEFT 15
// head/front occupies x 91..132.66666 and must move LEFT 42
//
// Those offsets reconstruct the uploaded "Deer baby.svg" assembled reference.

function drawSeparatedDeerBabySleepSkin(a) {
  const img = DEER_BABY_SLEEP_SEPARATED_IMAGE;
  if (!img.complete || !img.naturalWidth || !img.naturalHeight) return false;

  const r = Math.max(8, Number(a.r) || 18);
  const stageScale = UPLOADED_ANIMAL_STAGE_VISUAL_SCALE.baby || 1.78;

  // Measured from the uploaded separated sleep SVG:
  // source size 131.02001 × 47.42844
  // connected components:
  // tail bbox 0..16
  // body bbox 19..82
  // head bbox 89..130
  //
  // Use the same reconstruction idea as the awake deer:
  // tail stays in place, body shifts LEFT 15, head shifts LEFT 42.
  // Final assembled x ranges become:
  // tail 0..16, body 4..67, head 47..88  => overall width 89.
  const assembledW = 89.0;
  const assembledH = 47.42844;
  const assembledAspect = assembledW / assembledH;

  const drawH = r * 1.00 * stageScale;
  const drawW = drawH * assembledAspect;
  const scale = drawW / assembledW;
  const left = -drawW * 0.5;
  const top = -drawH * 0.5;

  ctx.save();
  ctx.fillStyle = "rgba(0,0,0,0.15)";
  ctx.beginPath();
  ctx.ellipse(-drawW * 0.03, drawH * 0.30, drawW * 0.31, drawH * 0.14, 0, 0, TAU);
  ctx.fill();

  const oldSmooth = ctx.imageSmoothingEnabled;
  const oldQuality = ctx.imageSmoothingQuality;
  ctx.imageSmoothingEnabled = true;
  try { ctx.imageSmoothingQuality = "high"; } catch (_) {}

  const srcW = img.naturalWidth;
  const srcH = img.naturalHeight;

  const tailX0 = 0.0 / 131.02001 * srcW;
  const tailX1 = 16.0 / 131.02001 * srcW;
  const bodyX0 = 19.0 / 131.02001 * srcW;
  const bodyX1 = 82.0 / 131.02001 * srcW;
  const headX0 = 89.0 / 131.02001 * srcW;
  const headX1 = 131.02001 / 131.02001 * srcW;

  // Tail final x = 0..16 — rotate around its connection to the body.
  ctx.save();
  ctx.translate(left + 15.0 * scale, 0);
  ctx.rotate(deerTailAngle);
  ctx.translate(-(left + 15.0 * scale), 0);
  ctx.drawImage(
    img,
    tailX0, 0, tailX1 - tailX0, srcH,
    left + 0.0 * scale, top,
    16.0 * scale, drawH
  );
  ctx.restore();

  // Body final x = 4..67 (19..82 shifted left by 15)
  ctx.drawImage(
    img,
    bodyX0, 0, bodyX1 - bodyX0, srcH,
    left + 4.0 * scale, top,
    63.0 * scale, drawH
  );

  // Head final x = 47..89 — separate head movement around the neck.
  ctx.save();
  ctx.translate(left + 49.0 * scale, deerHeadBob);
  ctx.rotate(deerHeadAngle);
  ctx.translate(-(left + 49.0 * scale), 0);
  ctx.drawImage(
    img,
    headX0, 0, headX1 - headX0, srcH,
    left + 47.0 * scale, top,
    42.0 * scale, drawH
  );
  ctx.restore();

  ctx.imageSmoothingEnabled = oldSmooth;
  try { ctx.imageSmoothingQuality = oldQuality; } catch (_) {}
  ctx.restore();
  return true;
}

function drawSeparatedDeerBabySkin(a) {
  const img = DEER_BABY_SEPARATED_IMAGE;
  if (!img.complete || !img.naturalWidth || !img.naturalHeight) return false;

  const r = Math.max(8, Number(a.r) || 18);
  const stageScale = UPLOADED_ANIMAL_STAGE_VISUAL_SCALE.baby || 1.78;
  const assembledAspect = 90.66667 / 47.42844;
  const drawH = r * 1.00 * stageScale;
  const drawW = drawH * assembledAspect;
  const scale = drawW / 90.66667;
  const left = -drawW * 0.5;
  const top = -drawH * 0.5;

  ctx.save();
  ctx.fillStyle = "rgba(0,0,0,0.15)";
  ctx.beginPath();
  ctx.ellipse(-drawW * 0.03, drawH * 0.30, drawW * 0.31, drawH * 0.14, 0, 0, TAU);
  ctx.fill();

  const oldSmooth = ctx.imageSmoothingEnabled;
  const oldQuality = ctx.imageSmoothingQuality;
  ctx.imageSmoothingEnabled = true;
  try { ctx.imageSmoothingQuality = "high"; } catch (_) {}

  const nowMs = performance.now();
  const recentlyMoved = (nowMs - (a._visualMoveAt || 0)) < 180;
  const actualMoveSpeed = (!a.sleeping && recentlyMoved) ? Math.max(0, Number(a._visualMoveSpeed) || 0) : 0;
  const normalMoveSpeed = Math.max(1, Number(a.speed) || animalSpeed("deer", "baby", !!a.owned) || 1);
  const moveRatio = Math.max(0, Math.min(1.25, actualMoveSpeed / normalMoveSpeed));
  const deerMotionT = nowMs * 0.001;
  const deerTailAngle = Math.sin(deerMotionT * (2.4 + moveRatio * 6.0) + (a.tailPhase || 0)) *
    (a.sleeping ? 0.035 : (0.08 + moveRatio * 0.18));
  const deerHeadAngle = Math.sin(deerMotionT * (1.9 + moveRatio * 3.4) + 0.8 + (a.tailPhase || 0) * 0.25) *
    (a.sleeping ? 0.025 : (0.055 + moveRatio * 0.10));
  const deerHeadBob = Math.cos(deerMotionT * (2.1 + moveRatio * 3.0) + 0.35) *
    r * (a.sleeping ? 0.004 : (0.008 + moveRatio * 0.012));

  // Draw the three truly separate connected components back into the exact
  // assembled positions from Deer baby.svg. Tail first, body second, head last.
  const srcW = img.naturalWidth;
  const srcH = img.naturalHeight;

  const tailX0 = 0 / 132.66666 * srcW;
  const tailX1 = 22.5 / 132.66666 * srcW;
  const bodyX0 = 26.75 / 132.66666 * srcW;
  const bodyX1 = 90.25 / 132.66666 * srcW;
  const headX0 = 91.0 / 132.66666 * srcW;
  const headX1 = 132.66666 / 132.66666 * srcW;

  // Tail: final x = 0..22.5 — wag from the body connection.
  ctx.save();
  ctx.translate(left + 21.0 * scale, 0);
  ctx.rotate(deerTailAngle);
  ctx.translate(-(left + 21.0 * scale), 0);
  ctx.drawImage(
    img,
    tailX0, 0, tailX1 - tailX0, srcH,
    left + 0 * scale, top,
    22.5 * scale, drawH
  );
  ctx.restore();

  // Middle/body: source 26.75..90.25, shift left 15 -> final 11.75..75.25
  ctx.drawImage(
    img,
    bodyX0, 0, bodyX1 - bodyX0, srcH,
    left + 11.75 * scale, top,
    63.5 * scale, drawH
  );

  // Head/front: source 91..132.66666, shift left 42 -> final 49..90.66666.
  // Rotate it independently so the deer visibly looks around while moving.
  ctx.save();
  ctx.translate(left + 51.0 * scale, deerHeadBob);
  ctx.rotate(deerHeadAngle);
  ctx.translate(-(left + 51.0 * scale), 0);
  ctx.drawImage(
    img,
    headX0, 0, headX1 - headX0, srcH,
    left + 49.0 * scale, top,
    41.66667 * scale, drawH
  );
  ctx.restore();

  ctx.imageSmoothingEnabled = oldSmooth;
  try { ctx.imageSmoothingQuality = oldQuality; } catch (_) {}
  ctx.restore();
  return true;
}

